    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: from address, a target counterparty address (we will deploy a benign callee),
    // an array of addresses for _tos (fuzzer supplies dynamic array), and a uint v
    function testFuzz_property(address from, address maybeCallee, address[] memory tos, uint256 v) public {
        // admissible domain: keep wide but ensure tos array length is within reasonable bounds to avoid huge loops
        vm.assume(tos.length <= 10);

        // We need a contract with code for caddress to avoid the low-level call to an EOA always succeeding.
        // Deploy a benign Callee that always returns true from the low-level call selector.
        BenignCallee callee = new BenignCallee();

        // Use the deployed callee's address as caddress parameter; still allow fuzz to vary other params
        address caddress = address(callee);

        // Call C.transfer and observe whether it returns false. The reference contract should never return false.
        bool ok;
        try c.transfer(from, caddress, tos, v) returns (bool r) {
            // if the call completed, r must not be false for the reference; record that it completed
            ok = (r != false);
        } catch {
            // if it reverted, that's acceptable for reference; mark ok = true (property is about never returning false)
            ok = true;
        }

        // single assertion: reference contract never returns false for any admissible input
        assertTrue(ok);
    }
}

