    C c;
    // Helper that accepts the low-level call and returns true to simulate successful external calls
    contract SuccessfulCallee {
        // signature: transferFrom(address,address,uint256)
        function transferFrom(address, address, uint256) external pure returns (bool) {
            return true;
        }
        // fallback to catch selector-encoded calls if needed
        fallback() external payable {
            // do nothing, implicitly succeeds
        }
    }

    function setUp() public { c = new C(); }

    // fuzzed parameters: from, calleeAddress (will be deployed helper so we use a bool to choose using helper), and dynamic array encoded via bytes
    function testFuzz_property(address from, uint256 v, bytes memory tosPacked) public {
        // We need a non-empty address[]; decode tosPacked to address[] but ensure at least one entry.
        // Keep domain wide: allow arbitrary packed bytes, but only proceed when it decodes to at least one address.
        // Each address is 20 bytes; require TosPacked length at least 20 and multiple of 20 to decode cleanly.
        if (tosPacked.length < 20) return; // skip this fuzz case (still admissible domain)
        if (tosPacked.length % 20 != 0) return; // skip malformed packing

        uint count = tosPacked.length / 20;
        address[] memory tos = new address[](count);
        for (uint i = 0; i < count; i++) {
            uint offset = i * 20;
            bytes20 b20;
            assembly {
                b20 := mload(add(add(tosPacked, 0x14), offset))
            }
            tos[i] = address(b20);
        }

        // Deploy adversarial helper that will accept the low-level call and indicate success.
        SuccessfulCallee helper = new SuccessfulCallee();
        address helperAddr = address(helper);

        // Ensure the tos array is non-empty per contract requirement
        vm.assume(tos.length > 0);

        // Perform the call and capture the returned boolean via try/catch to observe behavior
        bool ok;
        try c.transfer(from, helperAddr, tos, v) returns (bool ret) {
            // For the reference contract, ret should be true whenever all external calls succeeded.
            // We only observe by setting ok to (ret == true). The single assertion below will check ok.
            ok = ret;
        } catch {
            // If the call reverts, mark as false (but with our helper it should not revert)
            ok = false;
        }

        // The universal property: for any admissible input (non-empty tos and a callee whose external calls succeed),
        // the reference returns true. The mutant (which returns false) will cause this assertion to fail for some input.
        assertTrue(ok);
